    pub fn generate_and_execute_batch<I>(&self, paths: I, buffer_output: bool) -> ExitCode
    where
        I: Iterator<Item = PathBuf>,
    {
        let mut paths: Vec<_> = paths.collect();
        if paths.is_empty() {
            return ExitCode::Success;
        }
        paths.sort();

        // Position of the (single) argument that contains the placeholder(s).
        let path_arg_index = match self.args[1..].iter().position(ArgumentTemplate::has_tokens) {
            Some(index) => index,
            None => return ExitCode::Success,
        };

        // Fixed overhead of the command that stays the same across all batches: the executable
        // name and all of the other, non-placeholder arguments.
        let fixed_len = self.args[0].generate("", None).len()
            + self.args[1..]
                .iter()
                .enumerate()
                .filter(|&(index, _)| index != path_arg_index)
                .map(|(_, arg)| arg.generate("", None).len() + 1)
                .sum::<usize>();

        let max_len = max_command_line_length();

        let mut results = Vec::new();
        let mut batch: Vec<OsString> = Vec::new();
        let mut batch_len = fixed_len;

        for path in &paths {
            let generated = self.args[1 + path_arg_index]
                .generate(strip_current_dir(path), self.path_separator.as_deref());
            let generated_len = generated.len() + 1;

            if !batch.is_empty() && batch_len + generated_len > max_len {
                results.push(self.execute_batch(&batch, path_arg_index, buffer_output));
                batch.clear();
                batch_len = fixed_len;
            }

            batch_len += generated_len;
            batch.push(generated);
        }

        if !batch.is_empty() {
            results.push(self.execute_batch(&batch, path_arg_index, buffer_output));
        }

        merge_exitcodes(results)
    }

    /// Executes a single batch of the command, substituting `batch_args` for the placeholder
    /// argument at `path_arg_index`.
    fn execute_batch(
        &self,
        batch_args: &[OsString],
        path_arg_index: usize,
        buffer_output: bool,
    ) -> ExitCode {
        let mut cmd = Command::new(self.args[0].generate("", None));
        cmd.stdin(Stdio::inherit());
        cmd.stdout(Stdio::inherit());
        cmd.stderr(Stdio::inherit());

        for (index, arg) in self.args[1..].iter().enumerate() {
            if index == path_arg_index {
                cmd.args(batch_args);
            } else {
                cmd.arg(arg.generate("", None));
            }
        }

        execute_command(cmd, &Mutex::new(()), buffer_output)
    }
}

/// The maximum length (in bytes) of the argument/environment vector that is passed to a new
/// process. Batches of paths are split up in order to stay below this threshold, similar to what
/// `xargs` does.
#[cfg(all(unix, not(target_os = "redox")))]
fn max_command_line_length() -> usize {
    static DEFAULT: usize = 128 * 1024;
    // Reserve some headroom for the environment and other overhead that the OS also has to fit
    // into the same limit.
    static RESERVED: usize = 4 * 1024;

    let arg_max = unsafe { libc::sysconf(libc::_SC_ARG_MAX) };
    if arg_max <= 0 {
        return DEFAULT;
    }

    (arg_max as usize).saturating_sub(RESERVED).max(RESERVED)
}

#[cfg(not(all(unix, not(target_os = "redox"))))]
fn max_command_line_length() -> usize {
    128 * 1024
}

